"""Classic 9x9 Sudoku — command-line game loop."""
from sudoku import SudokuBoard

HELP = """Commands:
  <row> <col> <value>   Place a value, e.g.  3 5 7
  erase <row> <col>     Clear a cell, e.g.  erase 3 5
  check                 Report any mistakes on the board
  hint                  Reveal one correct value
  new                   Start a fresh puzzle
  help                  Show this help
  quit                  Exit the game"""


def parse(line):
    parts = line.strip().lower().split()
    if not parts:
        return None, None
    if parts[0] in ("quit", "exit"):
        return "quit", None
    if parts[0] in ("help", "?"):
        return "help", None
    if parts[0] in ("check", "hint", "new"):
        return parts[0], None
    if parts[0] == "erase":
        if len(parts) == 3 and all(p.isdigit() for p in parts[1:]):
            return "erase", (int(parts[1]) - 1, int(parts[2]) - 1)
        return "error", "Usage: erase <row 1-9> <col 1-9>"
    if len(parts) == 3 and all(p.isdigit() for p in parts):
        return "place", (int(parts[0]) - 1, int(parts[1]) - 1, int(parts[2]))
    return "error", "Unknown command. Type 'help' for the command list."


def main():
    print("Welcome to Sudoku! Fill the grid so every row, column")
    print("and 3x3 box contains the digits 1-9 exactly once.")
    board = SudokuBoard()
    print(HELP)
    while True:
        print()
        print(board.display())
        if board.is_complete():
            print("Congratulations! The puzzle is complete and correct.")
            break
        try:
            line = input("Move (row col value | check | hint | erase | new | quit): ")
        except (EOFError, KeyboardInterrupt):
            print("\nGoodbye!")
            break
        cmd, arg = parse(line)
        if cmd is None:
            continue
        if cmd == "quit":
            print("Goodbye!")
            break
        if cmd == "help":
            print(HELP)
        elif cmd == "error":
            print(arg)
        elif cmd == "place":
            r, c, v = arg
            ok, msg = board.place(r, c, v)
            print(msg)
            if board.is_complete():
                print()
                print(board.display())
                print("Congratulations! The puzzle is complete and correct.")
                break
        elif cmd == "erase":
            r, c = arg
            if board.erase(r, c):
                print("Cleared cell (%d,%d)." % (r + 1, c + 1))
            else:
                print("Cannot erase (%d,%d): out of range or a fixed given." % (r + 1, c + 1))
        elif cmd == "check":
            bad = board.mistakes()
            if bad:
                print("Mistakes at: " + ", ".join(
                    "(%d,%d)=%d" % (r + 1, c + 1, v) for r, c, v in bad))
